using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;

// Exercises only generated files under the isolated test directory. No discovery
// of the user's live configuration and no native game writes are used by tests.
internal static class NativeHotbarVerification {
 static void Check(bool value,string text){if(!value)throw new Exception(text);}
 static readonly byte[] Mask={0x25,0xa8,0x7e,0x91};
 static byte[] Crypt(byte[] bytes){return bytes.Select((b,n)=>(byte)(b^Mask[n%4])).ToArray();}
 static void Payload(Stream output,string text){var b=Encoding.UTF8.GetBytes(text);var len=BitConverter.GetBytes(b.Length+1);output.Write(len,0,4);output.Write(b,0,b.Length);output.WriteByte(0);}
 static string Preset(int index){if(index>1)return "{\"Name\":\"Empty\",\"Group\":0,\"Edit\":{}}";return "{\"Name\":\"Test · ñ\",\"Group\":0,\"Edit\":{"+string.Join(",",NativeHudFile.Tags.Select((t,n)=>"\""+t+"\":{\"Tag\":\""+t+"\",\"HO\":1.000001,\"Hide\":"+(n==1?"true":"false")+",\"Size\":0.93}"))+",\"Chat\":{\"Tag\":\"Chat\",\"Hide\":false,\"HO\":77.25}}}";}
 static byte[] Fixture(){using(var output=new MemoryStream()){Payload(output,"{\"Version\":2,\"Graphics\":\"Original\"}");output.Write(new byte[16],0,16);Payload(output,"{\r\n\"Version\":1\r\n}");for(byte n=1;n<=2;n++){var header=new byte[8];header[0]=n;header[7]=0x41;output.Write(header,0,8);Payload(output,"{\r\n\"Version\":1,\"Other\":\"Original\",\"HudEditPreset\":["+string.Join(",",Enumerable.Range(0,6).Select(Preset))+"]\r\n}");}var tail=new byte[8];tail[0]=3;output.Write(tail,0,8);Payload(output,"{\r\n\"Version\":1,\"GridOption\":8\r\n}");return Crypt(output.ToArray());}}
 static byte[] Rename(byte[] before){var doc=NativeHudFile.Read(before);using(var stream=new MemoryStream()){int cursor=0;foreach(var r in doc.Records){stream.Write(doc.Clear,cursor,r.SizeAt-cursor);Payload(stream,r.Text.Replace("Original","User edit"));cursor=r.End+1;}stream.Write(doc.Clear,cursor,doc.Clear.Length-cursor);return Crypt(stream.ToArray());}}
 static void Rejected(byte[] bytes){bool rejected=false;try{NativeHudFile.Build(bytes,true,null);}catch(InvalidDataException){rejected=true;}catch(IOException){rejected=true;}catch(ArgumentException){rejected=true;}Check(rejected,"Malformed or unsupported settings must be rejected");}
 static NativeHotbar Service(string root,string file,string backup,Func<bool> running,bool? value){var service=new NativeHotbar(root,false,running,backup);service.Configure(value,file);return service;}
 internal static void Run(string root){string folder=Path.Combine(root,"native-hud-cases");Directory.CreateDirectory(folder);var before=Fixture();var doc=NativeHudFile.Read(before);Check(doc.Groups.Count==4&&doc.Records.Count==4,"Two characters, two populated presets each, and non-HUD records");var on=NativeHudFile.Build(before,true,null);Check(on.Changed&&on.AllHidden&&on.Restore.Count==12,"Remember every original visibility per opaque record and preset");var off=NativeHudFile.Build(on.Bytes,false,on.Restore);Check(off.Bytes.SequenceEqual(before),"Hide then restore must recover every byte, including mixed original visibility");Check(!NativeHudFile.Build(on.Bytes,true,on.Restore).Changed,"An already-hidden bar is an exact no-op");
  byte[] edited=Rename(on.Bytes);var restored=NativeHudFile.Build(edited,false,on.Restore);Check(restored.Bytes.SequenceEqual(Rename(before)),"Restoring visibility preserves later unrelated edits to HUD data");
  var clear=Crypt(before);clear[0]=0xff;clear[1]=0xff;Rejected(Crypt(clear));for(int n=0;n<Math.Min(128,before.Length);n++)Rejected(before.Take(n).ToArray());Rejected(before.Take(before.Length-1).ToArray());clear=Crypt(before);var first=NativeHudFile.Read(before).Records[1];clear[first.SizeAt]=0;clear[first.SizeAt+1]=0;clear[first.SizeAt+2]=0;clear[first.SizeAt+3]=0;Rejected(Crypt(clear));
  var duplicate=Crypt(before);var records=NativeHudFile.Read(before).Records;Buffer.BlockCopy(duplicate,records[1].Start-12,duplicate,records[2].Start-12,8);Rejected(Crypt(duplicate));
  string file=Path.Combine(folder,"DeviceSetting_V2.dat"),backups=Path.Combine(folder,"backups");File.WriteAllBytes(file,before);bool game=true;var s=Service(root,file,backups,()=>game,true);s.Maintain(0);s.Maintain(2);Check(s.Pending&&File.ReadAllBytes(file).SequenceEqual(before)&&!Directory.Exists(backups),"A running game queues the choice without writing configuration or backups");game=false;s.Maintain(4);Check(File.ReadAllBytes(file).SequenceEqual(before),"Allow the game's settings flush to settle");s.Maintain(6);Check(!s.Pending&&File.ReadAllBytes(file).SequenceEqual(on.Bytes),"Apply queued hide only after game exit and settling");var saved=Directory.GetFiles(s.BackupDirectory,"*.dat");Check(saved.Length==1&&File.ReadAllBytes(saved[0]).SequenceEqual(before),"Verified original backup exists before mutation");var stamp=File.GetLastWriteTimeUtc(file);s.Maintain(8);s.Maintain(10);Check(File.GetLastWriteTimeUtc(file)==stamp&&Directory.GetFiles(s.BackupDirectory,"*.dat").Length==1,"Idle maintenance does not rewrite or multiply backups");
  File.WriteAllBytes(file,edited);var restarted=Service(root,file,backups,()=>false,false);restarted.Maintain(0);restarted.Maintain(2);Check(File.ReadAllBytes(file).SequenceEqual(Rename(before))&&!restarted.Pending,"Restore journal survives Helper restart without rolling back new HUD edits");Check(Directory.GetFiles(s.BackupDirectory,"*.dat").Length==2,"Restore also backs up the current file");
  string noWrite=Path.Combine(folder,"unused-backups");var unmanaged=Service(root,file,noWrite,()=>false,null);unmanaged.Maintain(0);unmanaged.Maintain(2);Check(!Directory.Exists(noWrite),"Default unset preference never writes or creates restore records");var preview=new NativeHotbar(root,true,()=>{throw new Exception("Preview checked the real game");},noWrite);preview.Configure(true,"invalid-path");preview.Inspect(0);preview.Maintain(0);Check(!Directory.Exists(noWrite),"Visual previews do no native HUD IO");
  File.WriteAllBytes(file,before);int checks=0;var race=Service(root,file,Path.Combine(folder,"race-backups"),()=>++checks>=4,true);race.Maintain(0);race.Maintain(2);Check(File.ReadAllBytes(file).SequenceEqual(before)&&race.Pending,"Game reopening during preparation prevents committing a queued change");
  int calls=0;var sourceRace=Service(root,file,Path.Combine(folder,"source-race"),()=>{if(++calls==4)File.WriteAllBytes(file,Rename(before));return false;},true);sourceRace.Maintain(0);sourceRace.Maintain(2);Check(File.ReadAllBytes(file).SequenceEqual(Rename(before))&&sourceRace.Pending,"Source changed after backup must be retained rather than overwritten");
  var corrupt=Service(root,file,backups,()=>false,true);File.WriteAllText(Path.Combine(corrupt.BackupDirectory,"active.json"),"{\"Version\":99}");var fault=Service(root,file,backups,()=>false,true);fault.Maintain(0);fault.Maintain(2);Check(File.ReadAllBytes(file).SequenceEqual(Rename(before)),"Invalid restore journal fails closed without changing settings");
  string absent=Path.Combine(folder,"later","DeviceSetting_V2.dat");var retry=Service(root,absent,Path.Combine(folder,"retry"),()=>false,true);Directory.CreateDirectory(Path.GetDirectoryName(absent));File.WriteAllBytes(absent,before);retry.Retry();retry.Maintain(0);retry.Maintain(2);Check(File.ReadAllBytes(absent).SequenceEqual(on.Bytes),"Retry resolves a previously missing configuration");
  string fixture=Path.Combine(root,"native-fixture.dat");int realGroups=0;if(File.Exists(fixture)){var real=File.ReadAllBytes(fixture);var read=NativeHudFile.Read(real);realGroups=read.Groups.Count;var liveOn=NativeHudFile.Build(real,true,null);Check(NativeHudFile.Build(liveOn.Bytes,false,liveOn.Restore).Bytes.SequenceEqual(real),"Read-only captured real V2 fixture round-trips byte-for-byte");var liveOff=NativeHudFile.Build(real,false,null);Check(NativeHudFile.Read(liveOff.Bytes).Groups.All(g=>g.Rows.All(r=>!(bool)r["Hide"])),"Real V2 fixture can reveal the manually hidden bars");}
  var options=new SkillSlotsOptions{HideNativeHotbar=true,NativeHotbarPath=file};var json=NativeHudFile.Json();var persisted=SkillSlotsOptions.Read(json.Deserialize<Dictionary<string,object>>(json.Serialize(new{skillSlots=options})));Check(persisted.HideNativeHotbar==true&&persisted.NativeHotbarPath==file,"Native hotbar choice persists with existing hotbar options");Check(SkillSlotsOptions.Read(new Dictionary<string,object>()).HideNativeHotbar==null,"Existing users get an unmanaged default");
  File.WriteAllText(Path.Combine(root,"native-hotbar-test.txt"),"PASS: lossless native V2 hide/restore; mixed flags, multiple opaque character records and presets; subsequent user edits retained; truncated/invalid/duplicate records rejected; running game queues with zero writes; exit settling; verified original and pre-restore backups; idle no-op; journal reload and corrupt journal rejection; game/source races prevent commit; retry discovery; preview isolation; nullable preference persistence. Read-only real V2 fixture groups: "+realGroups+". No live game setting was modified.");
 }
}
